  insert into public.brands (name, website, description, country, status) values ('Kate Ryan Skincare', 'https://www.kateryanskincare.com', 'Clinical-meets-natural skincare brand (EGF, DMAE, hyaluronic acid, vitamins) that runs its own affiliate program through UpPromote, explicitly inviting skincare enthusiasts, beauty bloggers and influencers, with marketing materials, a personalized 15% audience discount code, and payments 30 days after order fulfillment.', null, 'published') returning id into bid;
  insert into public.brand_categories (brand_id, category_id, is_primary) values (bid, (select id from public.categories where slug = 'skincare'), true);
  insert into public.affiliate_programs (brand_id, network, commission_rate, commission_notes, application_url, status, last_checked_at) values (bid, 'UpPromote', 10, 'Commission cap: UNCAPPED — stated in the program terms (see evidence). Creator saturation: unknown (see evidence). Rate as reported by https://www.kateryanskincare.com/blogs/news/introducing-the-kate-ryan-skincare-affiliate-program-join-us-in-spreading-the-glow.', 'https://www.kateryanskincare.com/blogs/news/introducing-the-kate-ryan-skincare-affiliate-program-join-us-in-spreading-the-glow', 'needs_review', now());
  insert into public.opportunities (brand_id, title, application_url, source_url, status, opportunity_type) values (bid, 'Kate Ryan Skincare Affiliate Program (UpPromote)', 'https://www.kateryanskincare.com/blogs/news/introducing-the-kate-ryan-skincare-affiliate-program-join-us-in-spreading-the-glow', null, 'unverified', 'ugc');
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://www.kateryanskincare.com/blogs/news/introducing-the-kate-ryan-skincare-affiliate-program-join-us-in-spreading-the-glow', 'brand_site', 'affiliate_program', 'Official brand blog announcement of the Kate Ryan Skincare Affiliate Program (run via UpPromote): affiliates earn a 10% commission on all orders referred through their unique links, receive a personalized 15% discount code for their audience, get marketing materials and support, and are paid 30 days after an order is fulfilled. The post invites skincare enthusiasts, beauty bloggers and influencers. Internal inconsistency recorded: the heading advertises a 90-day cookie window while the body text says commission is earned on purchases made within 30 days of the referral.', 'verified', now());
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://www.kateryanskincare.com/blogs/news/introducing-the-kate-ryan-skincare-affiliate-program-join-us-in-spreading-the-glow', 'brand_site', 'commission_cap', 'The official announcement states, of the 10% commission on all referred orders: ''your earning potential is limitless!'' — an explicit no-limit earnings statement on the brand''s own site, so commission_cap is recorded as uncapped. No creator-count or saturation data is published, so creator_saturation stays unknown.', 'verified', now());
  insert into public.brand_scores (brand_id, niche_fit, ugc_evidence, compensation, contact_access, opportunity_availability, credibility, explanation) values (bid, 24, 14, 16, 10, 8, 4, '{"compensation": "Clean published 10% on all orders plus an explicit ''earning potential is limitless'' statement (uncapped); payout timing published (30 days after fulfillment).", "contact_access": "Application form is linked from the official announcement; no public partnerships email.", "credibility": "Established ingredient-led brand with a loyal community per its own announcement; terms published on its own domain.", "niche_fit": "Pure skincare brand (serums, anti-aging, hydration) squarely in the beauty/skincare UGC niche.", "opportunity_availability": "Program publicly announced and open to apply; cookie terms on the announcement page are internally inconsistent (90-day heading vs 30 days in body).", "ugc_evidence": "Program announcement explicitly targets skincare enthusiasts, beauty bloggers and influencers and supplies marketing materials and a shareable audience discount code."}'::jsonb);
  insert into public.brands (name, website, description, country, status) values ('Good + Plenty Naturals', 'https://goodplusplenty.com', 'US natural beauty and personal care brand (Good + Plenty, LLC) running its own affiliate program under detailed published terms effective November 10, 2026: free to join, no minimum social following, a 10% starting commission with higher performance rates communicated later, and monthly ACH payouts on the 15th with a $10 minimum.', 'United States', 'published') returning id into bid;
  insert into public.brand_categories (brand_id, category_id, is_primary) values (bid, (select id from public.categories where slug = 'beauty'), true);
  insert into public.affiliate_programs (brand_id, network, commission_rate, commission_notes, application_url, status, last_checked_at) values (bid, 'In-house (own program; platform not named in terms)', 10, 'Commission cap: not stated in any published source found — needs review. Creator saturation: unknown (see evidence). Rate as reported by https://goodplusplenty.com/pages/affiliate-terms.', 'https://goodplusplenty.com/pages/affiliate-terms', 'needs_review', now());
  insert into public.opportunities (brand_id, title, application_url, source_url, status, opportunity_type) values (bid, 'Good + Plenty Naturals Affiliate Program', 'https://goodplusplenty.com/pages/affiliate-terms', null, 'unverified', 'ugc');
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://goodplusplenty.com/pages/affiliate-terms', 'brand_site', 'affiliate_program', 'Official Affiliate Program Terms & Conditions (effective November 10, 2026) on the brand''s own domain: participation is free, no purchase or minimum social media following is required, applicants must be 18+ and US-resident, and affiliates earn a 10% starting commission on qualifying purchases via their unique link or code, calculated after discounts excluding shipping and tax. Higher commission rates may become available based on sales performance, communicated when available. Commissions are paid monthly on the 15th via ACH with a $10 minimum payout.', 'verified', now());
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://goodplusplenty.com/pages/affiliate-terms', 'brand_site', 'creator_program_terms', 'The terms are written for content creators: affiliates must share authentic content and honest reviews, follow FTC disclosure rules (with example disclosure wording provided), and may promote through personal social media, blogs, websites and email newsletters; paid ads using the brand name require prior written approval. The terms contain no statement about an earnings cap, so commission_cap is unknown, and no creator counts are published, so creator_saturation is unknown.', 'verified', now());
  insert into public.brand_scores (brand_id, niche_fit, ugc_evidence, compensation, contact_access, opportunity_availability, credibility, explanation) values (bid, 24, 13, 13, 9, 8, 4, '{"compensation": "Clean 10% starting rate on official terms with a defined payout schedule; higher tiers unpublished and no cap statement, so compensation is solid but not top-tier.", "contact_access": "Full terms published on the brand''s own site; application route is via the program itself, no public email.", "credibility": "Detailed, current (Nov 2026) legal terms on the brand''s own domain from a named LLC.", "niche_fit": "Natural beauty and personal care products \u2014 a core UGC category.", "opportunity_availability": "Free to join, no minimum following, US residents 18+; applications are approved or declined at the brand''s discretion.", "ugc_evidence": "Terms explicitly govern creator content: authentic reviews required, FTC disclosure guidance with examples, promotion via social media and blogs expressly permitted."}'::jsonb);
  insert into public.brands (name, website, description, country, status) values ('by-cosmetics', 'https://by-cosmetics.com', 'Bali-based natural organic cosmetics brand (PT Bali Ytka) with its own on-site affiliate/referral program: partners register an account on the brand''s website, receive a partner code, and earn commission on referred sales, paid to bank or PayPal once a 500,000 Rp minimum is reached.', 'Indonesia', 'published') returning id into bid;
  insert into public.brand_categories (brand_id, category_id, is_primary) values (bid, (select id from public.categories where slug = 'beauty'), true);
  insert into public.affiliate_programs (brand_id, network, commission_rate, commission_notes, application_url, status, last_checked_at) values (bid, 'In-house (own website accounts)', null, 'Commission cap: not stated in any published source found — needs review. Creator saturation: unknown (see evidence). Rate as reported by https://by-cosmetics.com/en/about-us/affiliate-program.', 'https://by-cosmetics.com/en/about-us/affiliate-program', 'needs_review', now());
  insert into public.opportunities (brand_id, title, application_url, source_url, status, opportunity_type) values (bid, 'by-cosmetics Affiliate / Referral Program', 'https://by-cosmetics.com/en/about-us/affiliate-program', null, 'unverified', 'ugc');
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://by-cosmetics.com/en/about-us/affiliate-program', 'brand_site', 'affiliate_program', 'Official Affiliate Program terms on the brand''s own domain (operator PT Bali Ytka): participation is free; the commission for attracting and purchasing by a new client is 10% of net revenue (excluding delivery); commission size may be determined individually for each partner; payout is made within 10 days after reaching a minimum one-time payment amount of 500,000 Rp, to bank, PayPal or other account.', 'verified', now());
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://by-cosmetics.com/en/about-us/affiliate-program', 'brand_site', 'commission_rate_conflict', 'Rate conflict on the brand''s own page: the binding terms body states 10% of net revenue for a new client, while the same page''s program description block advertises ''20% commission, unique links, monthly payouts''. Because the brand''s own page conflicts with itself, commission_rate is recorded as null. The terms contain no earnings-cap statement (cap unknown) and publish no creator counts (saturation unknown).', 'needs_review', now());
  insert into public.brand_scores (brand_id, niche_fit, ugc_evidence, compensation, contact_access, opportunity_availability, credibility, explanation) values (bid, 22, 10, 8, 9, 7, 3, '{"compensation": "Rate cannot be settled: the brand''s own page conflicts (10% of net revenue in the terms vs 20% in the page description), so the rate is null and compensation scores low.", "contact_access": "Full terms and self-serve registration on the brand''s own site; no public email.", "credibility": "Named legal operator (PT Bali Ytka) with full published terms, but the self-conflicting rate on its own page lowers confidence.", "niche_fit": "Natural organic cosmetics from Bali \u2014 a genuine beauty/skincare fit, though a smaller international brand for a US-creator directory.", "opportunity_availability": "Open registration for individuals and businesses; minimum payout of 500,000 Rp and an Indonesia-based operator may limit practicality for US creators.", "ugc_evidence": "A referral/affiliate program open to individuals, but the terms are written generically for partners rather than specifically for content creators."}'::jsonb);
  insert into public.brands (name, website, description, country, status) values ('Alitura Naturals', 'https://alitura.com', 'Laguna Beach, California premium natural skincare brand (clay masks, serums, moisturizers built on superfood ingredients) listed as an affiliate advertiser on the Impact network; the brand publishes no affiliate program page on its own site that could be found, and third-party rate listings conflict.', 'United States', 'published') returning id into bid;
