  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://affililist.com/network/alitura', 'directory', 'commission_rate_conflict', 'AffiliList''s Alitura listing claims a 15-30% commission rate, which directly conflicts with CompareEPC''s 5% Impact figure. Because published sources conflict and the brand publishes no rate itself, commission_rate is recorded as null. No source publishes an earnings-cap statement (cap unknown) or creator counts (saturation unknown).', 'needs_review', now());
  insert into public.brand_scores (brand_id, niche_fit, ugc_evidence, compensation, contact_access, opportunity_availability, credibility, explanation) values (bid, 25, 10, 8, 6, 6, 4, '{"compensation": "Rate unsettleable across conflicting third-party listings (5% vs 15-30%) and unpublished by the brand, so the rate is null.", "contact_access": "No public partnerships contact or official program page found; access is only via the Impact dashboard.", "credibility": "Established, well-known natural skincare brand based in Laguna Beach, CA; the gap is program transparency, not brand legitimacy.", "niche_fit": "Premium natural skincare (masks, serums) \u2014 a strong skincare UGC fit with high average order values.", "opportunity_availability": "Program appears live on Impact, but nothing about it is published on the brand''s own site.", "ugc_evidence": "An affiliate program exists on Impact, but no creator-specific program page, content brief or UGC offer from the brand could be found."}'::jsonb);
