  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://brandid.app/blog/ulta-beauty-affiliate-program/', 'directory', 'affiliate_program', 'Brandid''s Ulta Beauty affiliate program guide (updated 2026) reports the program runs through Impact with a 2% default commission (up to 8% for top performers), a 24-hour cookie, monthly payouts and a $10 threshold, and notes Ulta also lists on Rakuten in some regions.', 'publicly_reported', now());
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://bloggingwizard.com/ulta-affiliate-program/', 'directory', 'commission_rate_conflict', 'BloggingWizard reports Ulta''s Rakuten program at 6% commission, while UpPromote''s directory lists 4% and Brandid reports a 2% Impact default (up to 8%). Published rates conflict across networks and sources (2% / 4% / 6% / up to 8%), so commission_rate is recorded as null. No source publishes an earnings-cap statement (cap unknown) or absolute creator counts (saturation unknown).', 'needs_review', now());
  insert into public.brand_scores (brand_id, niche_fit, ugc_evidence, compensation, contact_access, opportunity_availability, credibility, explanation) values (bid, 26, 12, 9, 8, 7, 5, '{"compensation": "Rates are low and conflict across networks and sources (2-8%), and the retailer publishes none itself, so the rate is null.", "contact_access": "Application and management run through the Rakuten and Impact dashboards; no public partnerships email found.", "credibility": "The largest US beauty retailer; maximum brand credibility.", "niche_fit": "Full-spectrum beauty retailer \u2014 makeup, skincare, hair and fragrance content all fit.", "opportunity_availability": "Programs are live on two major networks; approval is at the retailer''s discretion and rates vary by network and region.", "ugc_evidence": "Long-running affiliate presence on major networks used by beauty creators and publishers; no dedicated UGC offer published."}'::jsonb);
