  insert into public.brands (name, website, description, country, status) values ('Sephora', 'https://www.sephora.com', 'Global prestige beauty retailer whose own affiliate page confirms a partnership with Rakuten Advertising for its classic affiliate program, and which since September 2025 also runs My Sephora Storefront, a creator storefront program; Sephora does not publish its affiliate commission rate.', null, 'published') returning id into bid;
