  insert into public.opportunities (brand_id, title, application_url, source_url, status, opportunity_type) values (bid, 'Sephora Affiliate Program (Rakuten) + My Sephora Storefront', 'https://www.sephora.com/beauty/affiliates', null, 'unverified', 'ugc');
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://www.sephora.com/beauty/affiliates', 'brand_site', 'affiliate_program', 'Sephora''s official Beauty Affiliate Program page states it has partnered with Rakuten Advertising to provide the tools to earn commissions across 200+ brands and 13,000+ products, that joining is free, and that publishers sign up at Rakuten Advertising and email ra-join-sephora@mail.rakuten.com to apply. The page also introduces My Sephora Storefront, a newer way for creators to curate products and earn commission on purchases through their storefront. Sephora publishes no commission rate on the page.', 'verified', now());
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://reverbico.com/blog/sephora-affiliate-program/', 'directory', 'commission_rate_conflict', 'Reverbico''s 2026 guide reports Sephora does not publish its rate, with third-party reviews commonly reporting around 5% (some citing up to 10%) on a roughly 24-hour cookie via Rakuten, and the Storefront track reported at 15% at its September 2025 launch. Because the brand publishes no rate and third-party figures conflict, commission_rate is recorded as null. No source publishes an earnings-cap statement (cap unknown) or absolute creator counts (saturation unknown).', 'needs_review', now());
  insert into public.brand_scores (brand_id, niche_fit, ugc_evidence, compensation, contact_access, opportunity_availability, credibility, explanation) values (bid, 27, 15, 10, 13, 7, 5, '{"compensation": "The brand publishes no rate and third-party figures conflict (about 5%, up to 10%, Storefront reported at 15% at launch), so the rate is null despite the program''s scale.", "contact_access": "Official affiliate page on the brand''s own domain with a named Rakuten join email for applications.", "credibility": "Global prestige beauty retailer; maximum brand credibility.", "niche_fit": "The prestige beauty retailer \u2014 200+ brands and 13,000+ products of content material across makeup, skincare, hair and fragrance.", "opportunity_availability": "Free to join with manual review; the classic track''s cookie is reported as short (about 24 hours), which limits practical value.", "ugc_evidence": "Beyond the classic affiliate program, My Sephora Storefront is a creator-built storefront product, direct evidence of a creator monetization route."}'::jsonb);
