  insert into public.opportunities (brand_id, title, application_url, source_url, status, opportunity_type) values (bid, 'The Ordinary Affiliate Programme (Awin)', 'https://ui.awin.com/merchant-profile/29849', null, 'unverified', 'ugc');
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://ui.awin.com/merchant-profile/29849', 'affiliate_network', 'affiliate_program', 'Awin''s official merchant profile for The Ordinary confirms a live affiliate programme on the network with a 30-day attribution (cookie) period; the profile describes the brand''s clinical skincare positioning and publishes no commission rate.', 'verified', now());
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://bloggingwizard.com/the-ordinary-affiliate-program/', 'directory', 'commission_rate_conflict', 'BloggingWizard reports The Ordinary affiliate commission of up to 6%, while Lasso lists up to 10% and other directories cite 5-10% ranges. Published rates conflict and neither the brand nor the Awin profile publishes one, so commission_rate is recorded as null. No source publishes an earnings-cap statement (cap unknown) or absolute creator counts (saturation unknown).', 'needs_review', now());
  insert into public.brand_scores (brand_id, niche_fit, ugc_evidence, compensation, contact_access, opportunity_availability, credibility, explanation) values (bid, 27, 11, 9, 8, 7, 5, '{"compensation": "No rate published by the brand or its Awin profile, and third-party figures conflict, so the rate is null.", "contact_access": "Application via the Awin merchant profile; no public partnerships email.", "credibility": "DECIEM/Est\u00e9e Lauder-owned global skincare brand with a long track record.", "niche_fit": "One of the most-reviewed skincare brands in UGC \u2014 ingredient-led serums are core skincare content.", "opportunity_availability": "Programme confirmed live on Awin with a published 30-day attribution period; approval at the brand''s discretion.", "ugc_evidence": "A live network affiliate programme exists, but no creator-specific content program or UGC offer is published by the brand."}'::jsonb);
  insert into public.brands (name, website, description, country, status) values ('Kiehl''s', 'https://www.kiehls.com', 'L''Oréal-owned apothecary-heritage skincare brand (since 1851) running affiliate programmes through networks including Awin and Rakuten Advertising; Awin''s UK merchant profile publishes a 5% baseline commission with a 30-day cookie, while US rate listings conflict.', null, 'published') returning id into bid;
  insert into public.brand_categories (brand_id, category_id, is_primary) values (bid, (select id from public.categories where slug = 'skincare'), true);
  insert into public.affiliate_programs (brand_id, network, commission_rate, commission_notes, application_url, status, last_checked_at) values (bid, 'Awin / Rakuten Advertising', null, 'Commission cap: not stated in any published source found — needs review. Creator saturation: unknown (see evidence). Rate as reported by https://ui.awin.com/merchant-profile/15733?pid=51861&utm_source=getlasso.', 'https://ui.awin.com/merchant-profile/15733?pid=51861&utm_source=getlasso', 'needs_review', now());
  insert into public.opportunities (brand_id, title, application_url, source_url, status, opportunity_type) values (bid, 'Kiehl''s Affiliate Programme (Awin / Rakuten)', 'https://ui.awin.com/merchant-profile/15733?pid=51861&utm_source=getlasso', null, 'unverified', 'ugc');
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://ui.awin.com/merchant-profile/15733?pid=51861&utm_source=getlasso', 'affiliate_network', 'affiliate_program', 'Awin''s merchant profile for the Kiehl''s UK affiliate programme states registration is free, affiliates earn commission on sales at kiehls.co.uk, and publishes a 5% baseline commission with a 30-day cookie and daily data feed updates.', 'verified', now());
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://linkapprove.com/affiliate-programs/category/beauty-skincare', 'directory', 'commission_rate_conflict', 'LinkApprove lists Kiehl''s at 7% per sale with a 30-day cookie, Brandid''s comparison table lists up to 8%, and InfluencerRate''s FAQ cites 5-10% by category — US/global figures conflict with each other and sit above the 5% baseline on Awin''s UK profile. Because the rate for the main (US) program cannot be settled from published sources, commission_rate is recorded as null. No source publishes an earnings-cap statement (cap unknown) or absolute creator counts (saturation unknown).', 'needs_review', now());
  insert into public.brand_scores (brand_id, niche_fit, ugc_evidence, compensation, contact_access, opportunity_availability, credibility, explanation) values (bid, 26, 11, 10, 8, 7, 5, '{"compensation": "Awin''s UK profile does publish a 5% baseline, but US/global listings conflict (5-10%), so the headline rate is honestly null with the UK figure documented.", "contact_access": "Application via network merchant profiles; no public partnerships email.", "credibility": "L''Or\u00e9al-owned brand with 170+ years of apothecary heritage.", "niche_fit": "Heritage skincare staples (moisturizers, serums, body care) \u2014 a strong routine-content fit.", "opportunity_availability": "Programmes live on at least two networks with a published 30-day cookie on Awin; terms vary by region.", "ugc_evidence": "Live network affiliate programmes on Awin and Rakuten used by beauty publishers; no creator-specific UGC offer published."}'::jsonb);
  insert into public.brands (name, website, description, country, status) values ('Jefit', 'https://www.jefit.com', 'Workout-tracking app with 20M+ downloads and a 4.8 App Store rating. Its own affiliate program is built for creators and coaches and pays 30% of every new subscriber''s first payment, with an explicit no-cap policy, a personal code/link, and 10% off yearly Elite plans for followers.', null, 'published') returning id into bid;
  insert into public.brand_categories (brand_id, category_id, is_primary) values (bid, (select id from public.categories where slug = 'fitness'), true);
  insert into public.affiliate_programs (brand_id, network, commission_rate, commission_notes, application_url, status, last_checked_at) values (bid, 'Brand direct', 30, 'Commission cap: UNCAPPED — stated in the program terms (see evidence). Creator saturation: unknown (see evidence). Rate as reported by https://www.jefit.com/affiliates.', 'https://www.jefit.com/affiliates', 'needs_review', now());
  insert into public.opportunities (brand_id, title, application_url, source_url, status, opportunity_type) values (bid, 'Jefit Affiliate Program', 'https://www.jefit.com/affiliates', 'https://www.jefit.com/affiliates', 'unverified', 'ugc');
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://www.jefit.com/affiliates', 'official_program_page', 'affiliate_program', 'Official affiliate page: ''Share Jefit with your audience and earn 30% of every new subscriber''s first payment. No cap on what you can make.'' The FAQ answers ''How much can I earn?'' with ''30% of every new subscriber''s first payment. There''s no cap, so the more people you bring in, the more you earn.''', 'verified', now());
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://www.jefit.com/affiliates', 'official_program_page', 'affiliate_program', 'Program mechanics on the official page: affiliates get their own code and je.fit link; attribution covers a new subscriber''s first payment within 90 days; followers get 10% off a yearly Jefit Elite subscription; payouts are monthly once earnings reach $15, by PayPal, bank transfer or gift card (Venmo in the US).', 'verified', now());
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://www.jefit.com/affiliates', 'official_program_page', 'creator_program', 'The page is addressed to creators, coaches and athletes (''For creators & coaches''); every application is reviewed and answered within 48 hours; the brand cites 20M+ downloads and App Store / Google Play ratings of 4.8 and 4.4.', 'verified', now());
  insert into public.brand_scores (brand_id, niche_fit, ugc_evidence, compensation, contact_access, opportunity_availability, credibility, explanation) values (bid, 27, 17, 19, 6, 9, 5, '{"compensation": "30% of each new subscriber''s first payment with an explicit ''There''s no cap'' FAQ answer; held just below maximum because commission applies to the first payment only, not renewals.", "contact_access": "No partnerships email is published, but applications are reviewed with a reply promised within 48 hours.", "credibility": "Established fitness app citing 20M+ downloads and a 4.8 App Store rating on its own program page.", "niche_fit": "A mainstream workout app that fitness creators can demo inside their own training content, with a follower discount on yearly plans.", "opportunity_availability": "Open application on the brand''s own page, reviewed within 48 hours.", "ugc_evidence": "The program is explicitly built for creators and coaches, with personal codes/links designed for videos, stories and bios; no creator counts are published, so saturation stays unknown."}'::jsonb);
  insert into public.brands (name, website, description, country, status) values ('FightCamp', 'https://www.joinfightcamp.com', 'Connected at-home boxing gym combining premium equipment with punch-tracking technology and trainer-led boxing and kickboxing workouts. Its affiliate program runs on Awin and pays 7.5% commission on subscription sign-ups with a 30-day cookie and a dedicated affiliate team.', null, 'published') returning id into bid;
  insert into public.brand_categories (brand_id, category_id, is_primary) values (bid, (select id from public.categories where slug = 'fitness'), true);
  insert into public.brand_contacts (brand_id, contact_type, email, contact_url, source_url, verification_status, last_verified_at) values (bid, 'partnerships', 'patrick@joinfightcamp.com', null, 'https://ui.awin.com/merchant-profile/90331', 'needs_review', null);
  insert into public.affiliate_programs (brand_id, network, commission_rate, commission_notes, application_url, status, last_checked_at) values (bid, 'Awin', 7.5, 'Commission cap: not stated in any published source found — needs review. Creator saturation: unknown (see evidence). Rate as reported by https://ui.awin.com/merchant-profile/90331.', 'https://ui.awin.com/merchant-profile/90331', 'needs_review', now());
  insert into public.opportunities (brand_id, title, application_url, source_url, status, opportunity_type) values (bid, 'FightCamp Affiliate Program (Awin)', 'https://ui.awin.com/merchant-profile/90331', 'https://ui.awin.com/merchant-profile/90331', 'unverified', 'ugc');
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://ui.awin.com/merchant-profile/90331', 'network_profile', 'affiliate_program', 'FightCamp''s own Awin merchant profile: ''7.5% commission on all FightCamp subscription sign ups'', 30-day cookie length, text links and banners, seasonal ads and codes, incentives and bonuses, and a dedicated affiliate team; questions go to patrick@joinfightcamp.com.', 'verified', now());
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://ui.awin.com/merchant-profile/90331', 'network_profile', 'creator_program', 'The Awin profile names its target partners: ''Good affiliate partners include sites focused on: lifestyle bloggers, mommy bloggers, fitness bloggers, travel bloggers, and other related topics'', and describes the punch-tracking product and workout library.', 'verified', now());
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://ui.awin.com/merchant-profile/90331', 'third_party_directory', 'affiliate_program', 'Third-party listings have cited a flat per-sale fee via another network for FightCamp, which conflicts with the Awin profile''s 7.5% of subscription sign-ups; the 7.5% figure recorded here is the one on the brand''s own Awin merchant profile, and no cap statement appears on either source, so the cap stays unknown.', 'needs_review', now());
  insert into public.brand_scores (brand_id, niche_fit, ugc_evidence, compensation, contact_access, opportunity_availability, credibility, explanation) values (bid, 26, 14, 13, 11, 8, 4, '{"compensation": "7.5% on subscription sign-ups via Awin; a modest rate on subscriptions only, with no cap statement published, so the cap is unknown.", "contact_access": "A named affiliate contact email (patrick@joinfightcamp.com) is published on the brand''s Awin profile.", "credibility": "Established connected-fitness brand running a staffed program on Awin, a major network.", "niche_fit": "A demonstrable home-boxing product with tracking stats - strong material for fitness and home-gym creators.", "opportunity_availability": "Joinable through the Awin network profile.", "ugc_evidence": "The profile explicitly recruits fitness and lifestyle bloggers and offers banners, codes and bonuses; no creator counts are published, so saturation stays unknown."}'::jsonb);
  insert into public.brands (name, website, description, country, status) values ('French Fitness', 'https://frenchfitness.com', 'US fitness-equipment retailer (Benicia, California) selling its own French Fitness gym gear plus other brands through FitnessSuperstore.com. Its Affiliate & Creator Partner Program pays 6% on FrenchFitness.com purchases and 4% on FitnessSuperstore.com purchases, tracked by link and personal coupon code.', 'United States', 'published') returning id into bid;
  insert into public.brand_categories (brand_id, category_id, is_primary) values (bid, (select id from public.categories where slug = 'fitness'), true);
  insert into public.affiliate_programs (brand_id, network, commission_rate, commission_notes, application_url, status, last_checked_at) values (bid, 'Brand direct', 6, 'Commission cap: not stated in any published source found — needs review. Creator saturation: unknown (see evidence). Rate as reported by https://frenchfitness.com/affiliate-program/.', 'https://frenchfitness.com/affiliate-program/', 'needs_review', now());
  insert into public.opportunities (brand_id, title, application_url, source_url, status, opportunity_type) values (bid, 'French Fitness Affiliate & Creator Partner Program', 'https://frenchfitness.com/affiliate-program/', 'https://frenchfitness.com/affiliate-program/', 'unverified', 'ugc');
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://frenchfitness.com/affiliate-program/', 'official_program_page', 'affiliate_program', 'Official FAQ: ''6% on purchases at FrenchFitness.com, 4% on purchases at FitnessSuperstore.com''; commissions are paid Net 30 by PayPal once the balance reaches $100, with a 14-day hold for returns; the page publishes the company address (457 Industrial Way, Benicia, CA 94510) and phone.', 'verified', now());
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://frenchfitness.com/affiliate-program/', 'official_program_page', 'creator_program', 'The program is named the ''Affiliate & Creator Partner Program''; its FAQ confirms multi-platform publishers (YouTube, Instagram, blogs) are eligible, partners get a unique coupon code and auto-apply link, a live dashboard and a dedicated account manager; product seeding is limited and prioritises larger channels.', 'verified', now());
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://frenchfitness.com/affiliate-program/', 'official_program_page', 'affiliate_program', 'Eligibility and tracking caveats on the official page: US-based partners only, 18+, manual review in typically 2-3 business days, W-9/SSN required for tax compliance. The page''s cookie wording is inconsistent (30-day cookie in the benefits and FAQ, 7-day cookie in the rules section), and no earnings-cap statement is published, so the cap is unknown.', 'verified', now());
  insert into public.brand_scores (brand_id, niche_fit, ugc_evidence, compensation, contact_access, opportunity_availability, credibility, explanation) values (bid, 24, 15, 12, 6, 7, 4, '{"compensation": "6% on the brand''s own store (4% on the sister store) with high average order values on gym equipment; no cap statement is published, so the cap is unknown.", "contact_access": "No email is published, but partners get a dedicated account manager and the page prints a phone number and street address.", "credibility": "Operating US retailer with a physical California address, two storefronts and fully published program rules and tax requirements.", "niche_fit": "Home-gym and strength equipment is a natural review and setup-tour fit for fitness creators.", "opportunity_availability": "Open application with manual review (2-3 business days), but US-based partners only and a $100 payout minimum.", "ugc_evidence": "Explicitly a creator partner program with coupon codes for on-screen use and multi-platform eligibility; no creator counts are published, so saturation stays unknown."}'::jsonb);
  insert into public.brands (name, website, description, country, status) values ('Revolutti', 'https://www.revolutti.com', 'Small apparel brand run by its CEO, Daniel, selling clothing through its own store. Its Brand Ambassador program pays a Rank Journey commission starting at 3% of personal sales and rising to 10% as lifetime sales grow (ranks never reset), plus 50% of the earnings of ambassadors a member recruits, and states there is no limit on commissions.', null, 'published') returning id into bid;
  insert into public.brand_categories (brand_id, category_id, is_primary) values (bid, (select id from public.categories where slug = 'fashion'), true);
  insert into public.affiliate_programs (brand_id, network, commission_rate, commission_notes, application_url, status, last_checked_at) values (bid, 'Brand direct', 3, 'Commission cap: UNCAPPED — stated in the program terms (see evidence). Creator saturation: unknown (see evidence). Rate as reported by https://www.revolutti.com/brand-ambassador/.', 'https://www.revolutti.com/brand-ambassador/', 'needs_review', now());
  insert into public.opportunities (brand_id, title, application_url, source_url, status, opportunity_type) values (bid, 'Revolutti Brand Ambassador Program', 'https://www.revolutti.com/brand-ambassador/', 'https://www.revolutti.com/brand-ambassador/', 'unverified', 'ugc');
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://www.revolutti.com/brand-ambassador/', 'official_program_page', 'affiliate_program', 'Official page, ''The Sky''s the Limit'' section: ''Our affiliate program has no limit to the amount of commissions you can make each day, week, or month. The only limit is how much you can share and convert.''', 'verified', now());
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://www.revolutti.com/brand-ambassador/', 'official_program_page', 'affiliate_program', 'Rank Journey table on the official page: Rank 1 pays 3% of personal sales ($0-$999 lifetime sales), rising through 5%, 5.5%, 6%, 6.5%, 7%, 7.5% and 8% to 10% at Rank 10 ($25,000+); sales totals are never reset. Ambassadors generate links and QR codes from their affiliate account.', 'verified', now());
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://www.revolutti.com/brand-ambassador/', 'official_program_page', 'affiliate_program', 'Recruiter bonus on the official page: ''for every referral you bring in that sales anything in our store, you earn 50% equivalent of whatever they make'' - a multi-level style bonus on top of personal-sales commission, which creators should weigh before joining.', 'verified', now());
  insert into public.brand_scores (brand_id, niche_fit, ugc_evidence, compensation, contact_access, opportunity_availability, credibility, explanation) values (bid, 22, 13, 12, 4, 8, 2, '{"compensation": "Explicit no-limit wording, but the starting rate is only 3% and the 10% top rate needs $25,000 of lifetime personal sales; the 50%-of-recruits bonus is a multi-level structure, so compensation scores mid-range.", "contact_access": "No email or named contact is published on the ambassador page; everything runs through the affiliate account.", "credibility": "A small, young, CEO-fronted apparel brand with a recruiter-bonus structure; little independent track record is published.", "niche_fit": "General apparel is an easy fit for fashion creators, though the brand itself is niche and little-known.", "opportunity_availability": "Open self-serve registration from the ambassador page.", "ugc_evidence": "Ambassadors post generated links/QR codes on social media and get an account dashboard; no creator counts are published, so saturation stays unknown."}'::jsonb);
  insert into public.brands (name, website, description, country, status) values ('NOWIHT', 'https://nowiht.com', 'Women''s quiet-luxury ready-to-wear brand founded in 2020 (polo shirts and dresses, sweatshirts, hoodies, blouses, in cotton). Its Ambassador Program pays a personalised 1-10% commission with no limit on total earnings, but earnings are credited as store credit after the return period; referrals get 10% off their first order.', null, 'published') returning id into bid;
  insert into public.brand_categories (brand_id, category_id, is_primary) values (bid, (select id from public.categories where slug = 'fashion'), true);
  insert into public.affiliate_programs (brand_id, network, commission_rate, commission_notes, application_url, status, last_checked_at) values (bid, 'Brand direct', null, 'Commission cap: UNCAPPED — stated in the program terms (see evidence). Creator saturation: unknown (see evidence). Rate as reported by https://nowiht.com/referral.', 'https://nowiht.com/referral', 'needs_review', now());
  insert into public.opportunities (brand_id, title, application_url, source_url, status, opportunity_type) values (bid, 'NOWIHT Ambassador Program', 'https://nowiht.com/referral', 'https://nowiht.com/referral', 'unverified', 'ugc');
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://nowiht.com/referral', 'official_program_page', 'affiliate_program', 'Official referral page: ''1-10% Commission - Earn a personalized commission rate on every purchase made through your referral code. Your rate is determined based on factors such as your audience size, engagement, and the nature of our partnership'', with the bullets ''No limit on total earnings'' and ''Commission applies to all orders''.', 'verified', now());
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://nowiht.com/referral', 'official_program_page', 'affiliate_program', 'Material caveat on the official page: ''Credited as store credit after return period'' - ambassador earnings are paid in store credit, not cash. Because the 1-10% rate is set individually per ambassador, no single published rate settles, so commission_rate is recorded as null.', 'verified', now());
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://nowiht.com/referral', 'official_program_page', 'creator_program', 'Application on the official page asks for an Instagram handle and social media following; applications are reviewed within 3 to 5 business days; referrals receive 10% off their first order, valid on all products including sale items, for new customers only.', 'verified', now());
  insert into public.brand_scores (brand_id, niche_fit, ugc_evidence, compensation, contact_access, opportunity_availability, credibility, explanation) values (bid, 23, 14, 11, 4, 7, 3, '{"compensation": "''No limit on total earnings'' is stated explicitly, but the rate is a personalised 1-10% set after application and earnings are paid as store credit rather than cash, so compensation scores conservatively.", "contact_access": "No email is published; questions go through the site''s contact page and the application form.", "credibility": "Operating womenswear label founded in 2020 with clear program terms printed on its own page, but a small brand.", "niche_fit": "Quiet-luxury womenswear staples fit fashion and styling creators well, with a 10% first-order offer for their audience.", "opportunity_availability": "Application form on the official page, reviewed in 3-5 business days; the brand frames the program as exclusive/partnership-based.", "ugc_evidence": "The ambassador application is built around social following and Instagram handles; no creator counts are published, so saturation stays unknown."}'::jsonb);
  insert into public.brands (name, website, description, country, status) values ('Nexbelt', 'https://www.nexbelt.com', 'Ratchet-belt brand founded in 2010, selling EDC, golf, casual and dress belts and custom buckles for men, women and children. Its affiliate program, applied for through AvantLink, is designed for influencer, eCommerce, golf, outdoor and fashion businesses and lists ''No cap on commissions'' among its advantages; no percentage rate is published on the program page.', null, 'published') returning id into bid;
  insert into public.brand_categories (brand_id, category_id, is_primary) values (bid, (select id from public.categories where slug = 'fashion'), true);
  insert into public.affiliate_programs (brand_id, network, commission_rate, commission_notes, application_url, status, last_checked_at) values (bid, 'AvantLink', null, 'Commission cap: UNCAPPED — stated in the program terms (see evidence). Creator saturation: unknown (see evidence). Rate as reported by https://www.nexbelt.com/pages/nexbelt-affiliate-new.', 'https://www.nexbelt.com/pages/nexbelt-affiliate-new', 'needs_review', now());
  insert into public.opportunities (brand_id, title, application_url, source_url, status, opportunity_type) values (bid, 'Nexbelt Affiliate Program (AvantLink)', 'https://www.nexbelt.com/pages/nexbelt-affiliate-new', 'https://www.nexbelt.com/pages/nexbelt-affiliate-new', 'unverified', 'ugc');
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://www.nexbelt.com/pages/nexbelt-affiliate-new', 'official_program_page', 'affiliate_program', 'Official affiliate page advantages list includes ''No cap on commissions'' verbatim, alongside a tracking cookie, free US shipping and a 30-day return policy for uncut belts; the page states the program ''is designed to add a strong additional revenue stream to influencer, eCommerce, golf, outdoor, and fashion businesses'' and its Apply Now link goes to AvantLink.', 'verified', now());
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://www.nexbelt.com/pages/nexbelt-affiliate-new', 'official_program_page', 'affiliate_program', 'No commission percentage is published anywhere on the official program page - affiliates learn the rate inside AvantLink - so commission_rate is recorded as null rather than guessed. Terms note that application does not guarantee admittance and only approved coupons may be promoted.', 'verified', now());
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://www.nexbelt.com/pages/nexbelt-affiliate-new', 'official_program_page', 'affiliate_program', 'Brand background on the official page: ''Nexbelt was founded in 2010 and is the leading provider of high-quality ratchet belts'', with EDC, golf, casual and dress collections and custom buckles for men, women and children.', 'verified', now());
  insert into public.brand_scores (brand_id, niche_fit, ugc_evidence, compensation, contact_access, opportunity_availability, credibility, explanation) values (bid, 23, 13, 10, 4, 8, 4, '{"compensation": "''No cap on commissions'' is stated explicitly on the official page, but the percentage rate is not published at all, so compensation scores low until the rate is confirmed inside AvantLink.", "contact_access": "No email is published on the page; application and contact run through AvantLink.", "credibility": "Founded in 2010 and positioning itself as the leading ratchet-belt provider, running its program on the established AvantLink network.", "niche_fit": "A single demonstrable accessory (ratchet belts) that fits golf, EDC, outdoor and menswear-fashion creators.", "opportunity_availability": "Apply through the AvantLink link on the official page; admission is not guaranteed.", "ugc_evidence": "The program explicitly targets influencer businesses and permits promotion of approved coupons; no creator counts are published, so saturation stays unknown."}'::jsonb);
  insert into public.brands (name, website, description, country, status) values ('ALPAKA', 'https://alpakagear.com', 'Everyday-carry and travel gear brand (slings, backpacks and accessories) with a global storefront. Its Brand Ambassador program pays 10% cash commission on every qualifying purchase, gives followers 15% off, includes free products and VIP access to launches, and pays commissions via PayPal; applications are open worldwide.', null, 'published') returning id into bid;
  insert into public.brand_categories (brand_id, category_id, is_primary) values (bid, (select id from public.categories where slug = 'travel'), true);
  insert into public.affiliate_programs (brand_id, network, commission_rate, commission_notes, application_url, status, last_checked_at) values (bid, 'Brand direct', 10, 'Commission cap: not stated in any published source found — needs review. Creator saturation: unknown (see evidence). Rate as reported by https://alpakagear.com/en-de/pages/brand-ambassadors.', 'https://alpakagear.com/en-de/pages/brand-ambassadors', 'needs_review', now());
  insert into public.opportunities (brand_id, title, application_url, source_url, status, opportunity_type) values (bid, 'ALPAKA Brand Ambassador Program', 'https://alpakagear.com/en-de/pages/brand-ambassadors', 'https://alpakagear.com/en-de/pages/brand-ambassadors', 'unverified', 'ugc');
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://alpakagear.com/en-de/pages/brand-ambassadors', 'official_program_page', 'ambassador_program', 'Official ambassador page: ''As an ALPAKA Brand Ambassador, you''ll enjoy exclusive perks like free products and 10% cash commission on every qualifying purchase. Oh, and your friends, family + followers will get 15% off their purchase, too!'' plus VIP access to product launches.', 'verified', now());
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://alpakagear.com/en-de/pages/brand-ambassadors', 'official_program_page', 'ambassador_program', 'Program mechanics on the official page: apply and receive an answer by email within 2 weeks; no geographic restriction (''You can apply from anywhere''); a PayPal account is required because ''we pay Ambassador commissions via PayPal''; ambassadors promote on social media (IG, TikTok, etc.). No earnings-cap statement is published, so the cap is unknown.', 'verified', now());
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://alpakagear.com/en-de/pages/brand-ambassadors', 'third_party_directory', 'affiliate_program', 'Third-party affiliate directories separately list an ALPAKA affiliate offer at 8%, which appears to be a different channel from the 10% ambassador program on the brand''s own page; the 10% ambassador rate is the one recorded here.', 'publicly_reported', now());
  insert into public.brand_scores (brand_id, niche_fit, ugc_evidence, compensation, contact_access, opportunity_availability, credibility, explanation) values (bid, 25, 15, 13, 4, 8, 4, '{"compensation": "10% cash commission on every qualifying purchase plus free product; no cap statement is published, so the cap is unknown.", "contact_access": "No email is published; contact runs through the ambassador application, answered within about 2 weeks.", "credibility": "Established carry-goods brand with international storefronts and a defined, PayPal-paid ambassador program.", "niche_fit": "Slings and backpacks are core gear for travel, EDC and tech-carry creators, with a 15% follower discount to promote.", "opportunity_availability": "Open worldwide application on the official page.", "ugc_evidence": "The program is built around social promotion with free products and launch access; no creator counts are published, so saturation stays unknown."}'::jsonb);
  insert into public.brands (name, website, description, country, status) values ('GetYourGuide', 'https://www.getyourguide.com', 'Global marketplace for tours, activities and attraction tickets. Its own Partner Program pays new partners an 8% base commission per booking (earned once the activity takes place), with deep links, widgets and a creator storefront option, monthly statements and bank-transfer or PayPal payment, and no fees or commitments.', null, 'published') returning id into bid;
  insert into public.brand_categories (brand_id, category_id, is_primary) values (bid, (select id from public.categories where slug = 'travel'), true);
  insert into public.affiliate_programs (brand_id, network, commission_rate, commission_notes, application_url, status, last_checked_at) values (bid, 'Brand direct', 8, 'Commission cap: not stated in any published source found — needs review. Creator saturation: unknown (see evidence). Rate as reported by https://partner.getyourguide.support/hc/en-us/articles/13981068165917-Our-partner-program.', 'https://partner.getyourguide.support/hc/en-us/articles/13981068165917-Our-partner-program', 'needs_review', now());
  insert into public.opportunities (brand_id, title, application_url, source_url, status, opportunity_type) values (bid, 'GetYourGuide Partner Program', 'https://partner.getyourguide.support/hc/en-us/articles/13981068165917-Our-partner-program', 'https://partner.getyourguide.support/hc/en-us/articles/13981068165917-Our-partner-program', 'unverified', 'ugc');
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://partner.getyourguide.support/hc/en-us/articles/13981068165917-Our-partner-program', 'official_program_page', 'affiliate_program', 'Official Partner Resource Center: ''New partners receive an 8% base commission per booking. Commission is earned once the activity takes place, with flexible payment options including bank transfer and PayPal. Monthly commission statements provide transparency and easy tracking of your earnings.''', 'verified', now());
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://partner.getyourguide.support/hc/en-us/articles/13981068165917-Our-partner-program', 'official_program_page', 'affiliate_program', 'Program terms on the official page: ''No fees or commitments'' to start; integration options include deep links, widgets and an automatic widget; partners get analytics reports and a dedicated Partner Engagement Team; the brand states 88% of partners report satisfaction. No earnings-cap statement is published, so the cap is unknown.', 'verified', now());
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://partner.getyourguide.support/hc/en-us/articles/13981068165917-Our-partner-program', 'third_party_directory', 'affiliate_program', 'Third-party roundups report higher negotiated or network-specific rates for GetYourGuide (for example 7% via Awin and 8% via Travelpayouts); the 8% recorded here is the base rate on the brand''s own Partner Resource Center.', 'publicly_reported', now());
  insert into public.brand_scores (brand_id, niche_fit, ugc_evidence, compensation, contact_access, opportunity_availability, credibility, explanation) values (bid, 28, 13, 13, 5, 9, 5, '{"compensation": "8% base commission per booking from the brand''s own partner documentation; higher rates appear to be negotiated, and no cap statement is published, so the cap is unknown.", "contact_access": "A Partner Engagement Team supports partners, but no direct partnerships email is published on the page.", "credibility": "One of the largest global travel-experience marketplaces, with published partner documentation and an 88% partner-satisfaction claim.", "niche_fit": "Tours and activities in destinations worldwide fit almost any travel creator''s itinerary content, with widgets and storefronts for promotion.", "opportunity_availability": "Self-serve partner signup with no fees or commitment periods.", "ugc_evidence": "Widgets, deep links and creator storefronts are offered, but the program serves all partner types and publishes no creator counts, so saturation stays unknown."}'::jsonb);
  insert into public.brands (name, website, description, country, status) values ('Withlocals', 'https://www.withlocals.com', 'Marketplace for private tours and experiences led by local hosts in cities worldwide. Alongside its host program it runs an in-house affiliate program for websites, blogs and social platforms that pays 10% commission on every booking made through a referral, with full funnel reporting.', null, 'published') returning id into bid;
  insert into public.brand_categories (brand_id, category_id, is_primary) values (bid, (select id from public.categories where slug = 'travel'), true);
  insert into public.affiliate_programs (brand_id, network, commission_rate, commission_notes, application_url, status, last_checked_at) values (bid, 'Brand direct', 10, 'Commission cap: not stated in any published source found — needs review. Creator saturation: unknown (see evidence). Rate as reported by https://www.withlocals.com/info/partners/.', 'https://www.withlocals.com/info/partners/', 'needs_review', now());
  insert into public.opportunities (brand_id, title, application_url, source_url, status, opportunity_type) values (bid, 'Withlocals Affiliate Program', 'https://www.withlocals.com/info/partners/', 'https://www.withlocals.com/info/partners/', 'unverified', 'ugc');
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://www.withlocals.com/info/partners/', 'official_program_page', 'affiliate_program', 'Official partners page: ''If you run a website, blog, or social media platform, you can partner directly with Withlocals through our in house affiliate program. You get full visibility into your performance with detailed funnel reporting, so you can track clicks, bookings, and conversion. For every booking made through your referral, you earn a 10% commission.''', 'verified', now());
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://www.withlocals.com/info/partners/', 'official_program_page', 'affiliate_program', 'Application runs through the ''Apply to become a Withlocals Affiliate'' form linked from the official partners page; the page describes the program as ''Simple to set up, transparent to manage, and built to scale with you.'' No earnings-cap statement is published, so the cap is unknown.', 'verified', now());
  insert into public.brand_scores (brand_id, niche_fit, ugc_evidence, compensation, contact_access, opportunity_availability, credibility, explanation) values (bid, 25, 13, 14, 4, 8, 4, '{"compensation": "10% commission on every referred booking, paid by the brand''s in-house program; no cap statement is published, so the cap is unknown.", "contact_access": "No email is published; application is via the form linked from the partners page.", "credibility": "Established local-experiences marketplace with a defined in-house affiliate program and funnel reporting.", "niche_fit": "Local-led tours and food experiences map directly onto authentic, story-driven travel content.", "opportunity_availability": "Open application via the partners page form.", "ugc_evidence": "The program explicitly welcomes social media platforms as partners and provides funnel reporting; no creator counts are published, so saturation stays unknown."}'::jsonb);
  insert into public.brands (name, website, description, country, status) values ('Heymondo', 'https://heymondo.com', 'Barcelona-based travel insurance brand selling customisable trip policies. Its affiliate program is aimed at travel influencers: affiliates apply by form and receive a unique affiliate URL, dashboard access and marketing materials, but the commission rate is not published on the program page - the brand asks affiliates to consult it about benefits.', 'Spain', 'published') returning id into bid;
  insert into public.brand_categories (brand_id, category_id, is_primary) values (bid, (select id from public.categories where slug = 'travel'), true);
  insert into public.affiliate_programs (brand_id, network, commission_rate, commission_notes, application_url, status, last_checked_at) values (bid, 'Brand direct', null, 'Commission cap: not stated in any published source found — needs review. Creator saturation: unknown (see evidence). Rate as reported by https://heymondo.com/affiliate-program/.', 'https://heymondo.com/affiliate-program/', 'needs_review', now());
  insert into public.opportunities (brand_id, title, application_url, source_url, status, opportunity_type) values (bid, 'Heymondo Affiliate Program for Travel Influencers', 'https://heymondo.com/affiliate-program/', 'https://heymondo.com/affiliate-program/', 'unverified', 'ugc');
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://heymondo.com/affiliate-program/', 'official_program_page', 'affiliate_program', 'Official affiliate page (''Affiliate program for travel influencers''): joining steps are to fill in the form, then ''Receive everything you need: Your unique affiliate URL, dashboard access, marketing materials''; benefits are handled case by case - ''Consult with us about the benefits of being an affiliate for your travel insurance.'' The page prints the company address: Carrer d''Alaba 140, Barcelona, Spain.', 'verified', now());
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://heymondo.com/affiliate-program/', 'official_program_page', 'affiliate_program', 'No commission rate is published on the official program page, and third-party sources conflict (figures from about 7.5% to 15% appear across networks and roundups), so commission_rate is recorded as null and the cap as unknown rather than guessed.', 'needs_review', now());
  insert into public.brand_scores (brand_id, niche_fit, ugc_evidence, compensation, contact_access, opportunity_availability, credibility, explanation) values (bid, 24, 13, 8, 5, 7, 4, '{"compensation": "The official page publishes no rate and third-party figures conflict, so compensation scores low until terms are confirmed at application; cap unknown.", "contact_access": "Contact is form-based on the program page, with the company''s Barcelona address published.", "credibility": "Established Spanish travel-insurance brand with a dedicated influencer affiliate page and published company address.", "niche_fit": "Travel insurance is a practical, repeatable recommendation for travel creators, and the program page is written for travel influencers specifically.", "opportunity_availability": "Form application on the official page; the team replies to discuss terms.", "ugc_evidence": "The program is explicitly pitched at travel influencers with a dashboard and marketing materials; no creator counts are published, so saturation stays unknown."}'::jsonb);
  insert into public.brands (name, website, description, country, status) values ('The Maca Team', 'https://www.themacateam.com', 'Specialist brand focused exclusively on organic Peruvian maca since 2009, selling maca powders, capsules, extracts, chips and blends in red, black, yellow and tri-color varieties through its own store, with a direct affiliate program for wellness creators and educators.', null, 'published') returning id into bid;
