  insert into public.affiliate_programs (brand_id, network, commission_rate, commission_notes, application_url, status, last_checked_at) values (bid, 'Brand direct / AvantLink', 20, 'Commission cap: UNCAPPED — stated in the program terms (see evidence). Creator saturation: unknown (see evidence). Rate as reported by https://www.themacateam.com/maca-affiliate-program/.', 'https://www.themacateam.com/maca-affiliate-program/', 'needs_review', now());
  insert into public.opportunities (brand_id, title, application_url, source_url, status, opportunity_type) values (bid, 'The Maca Team Affiliate Program', 'https://www.themacateam.com/maca-affiliate-program/', 'https://www.themacateam.com/maca-affiliate-program/', 'unverified', 'ugc');
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://www.themacateam.com/maca-affiliate-program/', 'official_site', 'affiliate', 'The Maca Team''s official affiliate page publishes a 20% commission on qualifying referred sales of its organic Peruvian maca products and states verbatim: ''There is no cap on how much you can earn. The more qualified customers you refer, the more commission you can generate.'' Applications run through the brand''s own direct affiliate program, with an AvantLink network option also offered on the same page. The cap is verified uncapped on the brand''s own wording.', 'verified', now());
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://www.themacateam.com/maca-affiliate-program/', 'official_site', 'ugc_collab', 'The same page says the program is built for content creators, wellness educators, bloggers, recipe creators, practitioners and publishers, and provides referral links, marketing images, banners, text links, approved brand copy and a tracking dashboard inside the affiliate portal.', 'verified', now());
  insert into public.brand_scores (brand_id, niche_fit, ugc_evidence, compensation, contact_access, opportunity_availability, credibility, explanation) values (bid, 25, 14, 18, 8, 8, 4, '{"niche_fit": "A single-ingredient superfood specialist fits plant-based, smoothie, recipe and men''s/women''s wellness creator content with deep educational material to promote.", "ugc_evidence": "A public program page explicitly recruiting content creators and recipe creators, with banners, images and approved copy supplied; no creator counts were published on fetched pages.", "compensation": "20% flat on qualifying sales with a verified ''no cap on how much you can earn'' statement on the official page.", "contact_access": "No program email is published on the fetched page (a phone number is); joining and contact run through the affiliate portal, so access is scored mid-range.", "opportunity_availability": "Apply to the direct program on the official page, or join via AvantLink; approval required.", "credibility": "Maca-only specialist operating since 2009 with a deep product line and educational guides, per its own pages."}'::jsonb);
  insert into public.brands (name, website, description, country, status) values ('BUBS Naturals', 'https://www.bubsnaturals.com', 'Performance-wellness brand best known for collagen peptides, MCT oil creamer and electrolyte products, sold through its own store with separate Creator (Social Snowball) and Affiliate (Everflow) partner tracks.', null, 'published') returning id into bid;
  insert into public.brand_categories (brand_id, category_id, is_primary) values (bid, (select id from public.categories where slug = 'health'), true);
  insert into public.affiliate_programs (brand_id, network, commission_rate, commission_notes, application_url, status, last_checked_at) values (bid, 'Social Snowball', 20, 'Commission cap: UNCAPPED — stated in the program terms (see evidence). Creator saturation: unknown (see evidence). Rate as reported by https://www.bubsnaturals.com/pages/affiliate.', 'https://www.bubsnaturals.com/pages/affiliate', 'needs_review', now());
  insert into public.opportunities (brand_id, title, application_url, source_url, status, opportunity_type) values (bid, 'BUBS Naturals Creator Program (Social Snowball) / Affiliate Program (Everflow)', 'https://www.bubsnaturals.com/pages/affiliate', 'https://www.bubsnaturals.com/pages/affiliate', 'unverified', 'ugc');
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://www.bubsnaturals.com/pages/affiliate', 'official_site', 'affiliate', 'BUBS Naturals'' official Affiliate & Creator Program page states creators earn 20% commission on every sale with ''Unlimited earning'', give their audience 20% off with a personal code, receive a free welcome gift, and apply via Snowball (Social Snowball), with payouts monthly once a $100 threshold is met after a 30-day hold. A separate Affiliate track for publishers runs performance-based tiered commissions through Everflow. The creator track''s earnings are stated as unlimited on the brand''s own page, so the cap is recorded as uncapped.', 'verified', now());
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://www.bubsnaturals.com/pages/affiliate', 'official_site', 'ugc_collab', 'The same page defines Creators as influencers, UGC creators, athletes, wellness coaches and storytellers on Instagram, TikTok, YouTube or podcasts who share content through discount codes on social, with custom tracking and dashboard and first access to launches and collabs.', 'verified', now());
  insert into public.brand_scores (brand_id, niche_fit, ugc_evidence, compensation, contact_access, opportunity_availability, credibility, explanation) values (bid, 27, 17, 18, 6, 7, 4, '{"niche_fit": "Collagen, MCT creamer and electrolytes are staple, demo-able products for fitness, adventure and daily-routine wellness content.", "ugc_evidence": "A dedicated creator track explicitly naming UGC creators and social platforms, with personal codes, a free welcome gift and launch access; no creator counts were published on fetched pages.", "compensation": "20% on every sale for creators with earnings stated as ''Unlimited'' on the official page - verified uncapped.", "contact_access": "No program email is published on the fetched official page; application and support run through the Snowball/Everflow platforms.", "opportunity_availability": "Application via Social Snowball for creators or Everflow for publishers; the page frames it as an exclusive partner group, so availability is scored conservatively.", "credibility": "Established collagen brand with a long-running partner program across multiple networks and published payout terms."}'::jsonb);
  insert into public.brands (name, website, description, country, status) values ('The Protein Works', 'https://www.theproteinworks.com', 'Sports-nutrition brand selling protein powders, supplements and functional foods through its own store, running an affiliate programme on Partnerize (regional programmes including the USA) plus a separate Influencer Programme.', null, 'published') returning id into bid;
  insert into public.brand_categories (brand_id, category_id, is_primary) values (bid, (select id from public.categories where slug = 'health'), true);
