  insert into public.brand_contacts (brand_id, contact_type, email, contact_url, source_url, verification_status, last_verified_at) values (bid, 'partnerships', 'influencers@proteinworks.com', null, 'https://www.theproteinworks.com/affiliate-programme', 'verified', now());
  insert into public.affiliate_programs (brand_id, network, commission_rate, commission_notes, application_url, status, last_checked_at) values (bid, 'Partnerize', 12, 'Commission cap: UNCAPPED — stated in the program terms (see evidence). Creator saturation: unknown (see evidence). Rate as reported by https://www.theproteinworks.com/affiliate-programme.', 'https://www.theproteinworks.com/affiliate-programme', 'needs_review', now());
  insert into public.opportunities (brand_id, title, application_url, source_url, status, opportunity_type) values (bid, 'The Protein Works Affiliate Programme (Partnerize) & Influencer Programme', 'https://www.theproteinworks.com/affiliate-programme', 'https://www.theproteinworks.com/affiliate-programme', 'unverified', 'ugc');
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://www.theproteinworks.com/affiliate-programme', 'official_site', 'affiliate', 'The Protein Works'' official affiliate programme page publishes its commission structure as up to 12% commission for new customers and up to 6% for existing customers on a 30-day cookie, and states verbatim: ''No limit on the amount you can earn.'' Applications run through Partnerize (join.partnerize.com), with regional programmes including the USA. The recorded 12% is the published new-customer ceiling, not a base rate. The cap is verified uncapped on the brand''s own wording.', 'verified', now());
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://www.theproteinworks.com/affiliate-programme', 'official_site', 'ugc_collab', 'The same page runs a separate Influencer Programme paying 15% commission on each new customer, with a complimentary onboarding product bundle, for creators with over 1.5K social followers who create content on Instagram, TikTok and YouTube, and publishes affiliates@proteinworks.com and influencers@proteinworks.com.', 'verified', now());
  insert into public.brand_scores (brand_id, niche_fit, ugc_evidence, compensation, contact_access, opportunity_availability, credibility, explanation) values (bid, 24, 15, 15, 13, 8, 5, '{"niche_fit": "Protein and sports nutrition are core fitness-creator products with strong recipe, review and routine content angles.", "ugc_evidence": "A dedicated Influencer Programme recruiting social creators with product bundles and social features, alongside the publisher affiliate programme; no creator counts were published.", "compensation": "Up to 12% (new customers) via Partnerize and 15% for influencers on new customers, with a verified ''No limit on the amount you can earn'' statement.", "contact_access": "Two published programme emails (affiliates@ and influencers@) on the official page.", "opportunity_availability": "Apply via Partnerize for the regional programme (USA included) with brand assessment; influencer track asks for 1.5K+ followers.", "credibility": "Long-established sports-nutrition retailer running structured programmes on a major network across multiple regions."}'::jsonb);
  insert into public.brands (name, website, description, country, status) values ('Fit Body Weight Loss', 'https://fitbodyweightloss.com', 'Weight-loss and wellness brand founded by Master Nutritionist Christina Jordan, selling medical-grade supplements and metabolic/nutritional therapy programs through its own store, with a free Ambassador Program for wellness promoters.', null, 'published') returning id into bid;
