  insert into public.opportunities (brand_id, title, application_url, source_url, status, opportunity_type) values (bid, 'Fit Body Weight Loss Ambassador Program', 'https://fitbodyweightloss.com/ambassadorprogram/', 'https://fitbodyweightloss.com/ambassadorprogram/', 'unverified', 'ugc');
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://fitbodyweightloss.com/ambassadorprogram/', 'official_site', 'affiliate', 'Fit Body Weight Loss''s official Ambassador Program page publishes a 20% commission on every referred sale, no minimum payout, no sign-up fee and no minimum sales requirement, paid monthly. Its FAQ answers ''Is there a cap on how much I can earn?'' with, verbatim: ''No. You have unlimited earning potential.'' The cap is verified uncapped on the brand''s own page.', 'verified', now());
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://fitbodyweightloss.com/ambassadorprogram/', 'official_site', 'ugc_collab', 'The same page says ambassadors earn by placing banners or links on their website or social media posts, receive a personal 15%-off coupon code for referrals within 24-48 hours, a 15% lifetime ambassador discount, and ongoing online nutrition education.', 'verified', now());
  insert into public.brand_scores (brand_id, niche_fit, ugc_evidence, compensation, contact_access, opportunity_availability, credibility, explanation) values (bid, 20, 11, 17, 6, 8, 3, '{"niche_fit": "Weight-loss supplements and coaching fit transformation and wellness-journey content, a narrower and more claim-sensitive niche than general wellness.", "ugc_evidence": "A public ambassador page built around website and social-media promotion with coupon codes; no creator counts were published on fetched pages.", "compensation": "20% on every sale with a verified FAQ answer of no cap and unlimited earning potential, and no minimum payout.", "contact_access": "No programme email is published on the fetched page; joining runs through the on-site application.", "opportunity_availability": "Free application on the official page, open to all body types, ages and backgrounds, with brand approval.", "credibility": "Founder-led clinic-style brand with bold outcome claims on its own pages, so credibility is held at 3."}'::jsonb);
