  insert into public.brands (name, website, description, country, status) values ('Zerorez', 'https://www.zerorez.com', 'US home-cleaning services brand (carpet, area rug, upholstery, tile and grout, air duct and hardwood cleaning) built on its Zero Residue / Zr Water cleaning technology, with 70+ locations across the United States. Its affiliate program pays creators and publishers a flat commission for every completed job they refer.', 'United States', 'published') returning id into bid;
