  insert into public.affiliate_programs (brand_id, network, commission_rate, commission_notes, application_url, status, last_checked_at) values (bid, 'Impact', null, 'Commission cap: UNCAPPED — stated in the program terms (see evidence). Creator saturation: unknown (see evidence). Rate as reported by https://www.zerorez.com/blog/zerorez-affiliate-program.', 'https://www.zerorez.com/affiliates', 'needs_review', now());
  insert into public.opportunities (brand_id, title, application_url, source_url, status, opportunity_type) values (bid, 'Zerorez Affiliate Program — flat $40 per completed job via Impact, no limit on earnings', 'https://www.zerorez.com/affiliates', 'https://www.zerorez.com/blog/zerorez-affiliate-program', 'unverified', 'ugc');
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://www.zerorez.com/blog/zerorez-affiliate-program', 'official_site', 'affiliate', 'Official Zerorez blog post announcing the affiliate program, fetched in full: ''You will earn $40 for every job you send our way, with no limit to how much you can earn!'' Program features: $40 commission for completed jobs, 60-day cookie duration, monthly payouts, a dedicated affiliate manager and a monthly affiliate newsletter. Sign-up runs through Impact (the post links to the Impact Zerorez signup page and directs applicants to zerorez.com/affiliates). Open to anyone with a social media channel, email list, blog, platform or website; the brand says it especially encourages lifestyle, home decor, cleaning, real estate and family creators. The explicit ''no limit to how much you can earn'' statement on the brand''s own page makes the commission cap UNCAPPED. The pay is a flat $40 bounty per completed job, not a percentage, so commission_rate is null.', 'verified', now());
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://www.zerorez.com/blog/zerorez-affiliate-program', 'official_site', 'general', 'The same official post states Zerorez has operated for over 20 years, holds over 190,000 5-star Google reviews at a 4.9-star average, has more than 70 US locations, and pays commission on carpet, area rug, upholstery, tile and grout, pet spot/odor, mattress, stone, air duct and hardwood floor cleaning services. This affiliate program is separate from Zerorez''s customer Refer-A-Friend scheme ($25 gift card), which is not the route recorded here.', 'verified', now());
  insert into public.brand_scores (brand_id, niche_fit, ugc_evidence, compensation, contact_access, opportunity_availability, credibility, explanation) values (bid, 24, 16, 17, 12, 9, 4, '{"compensation": "Flat $40 per completed job with an explicit no-limit statement, a 60-day cookie and monthly payouts \u2014 strong, simple economics for local-service content", "contact_access": "Open application via Impact with a dedicated affiliate manager promised on the official post; no public program email published", "credibility": "20+ years operating, 190,000+ 5-star Google reviews and 70+ locations, all stated on the brand''s own page", "niche_fit": "Home cleaning before/after content is a proven, highly demonstrable UGC format for home and lifestyle creators", "opportunity_availability": "Free to join, open to social channels, blogs and websites of any size per the official post", "ugc_evidence": "Official announcement explicitly recruits people who share cleaning tips and healthier-living content online, and says the brand loves customer reviews and social media mentions"}'::jsonb);
