  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://us.smartmiglobal.com/pages/affiliate-program', 'official_site', 'affiliate', 'Official Smartmi US affiliate page fetched in full: ''Earn up to 15% Commission On Every Sale, and More'', with monthly incentive campaigns, extra bonuses and higher rates during festival events. The page states the program ''invites social media producers, review sites, bloggers, coupon sites and other website owners'', is free to join, tracks sales for 30 days after a click, and pays monthly once an order is confirmed and past the 15-day return window. ''Up to 15%'' is a rate ceiling, recorded as the published rate; the page makes no statement about an earnings cap, so the cap is unknown.', 'verified', now());
