  insert into public.brands (name, website, description, country, status) values ('Nom Nom', 'https://www.nomnomnow.com', 'Fresh pet food brand (Nom Nom, formerly NomNomNow) selling gently cooked, vet-developed dog meals personalized by age, weight and activity, prepared in its own kitchens and delivered by subscription; part of the Mars Petcare family. Its affiliate program pays commissions on every new customer, with the rate held inside the network login.', 'United States', 'published') returning id into bid;
