  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://alanslui.com/decisions/dog-affiliate-programmes/', 'listing', 'affiliate', 'Programme comparison checked 30 Oct 2026 against merchants'' own pages and network profiles: Nom Nom''s own page publishes no rate — it says only ''Commissions on every new customer'' — and the rate sits behind a Rakuten login. Because the brand itself does not publish a rate, commission_rate is null.', 'publicly_reported', now());
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://getlasso.co/affiliate/nom-nom/', 'listing', 'affiliate', 'Lasso''s Nom Nom listing reports a flat $24-$80 per sale with a 30-day cookie, while a March 2026 program comparison reports 15% via ShareASale with a $50 minimum payout. The third-party figures conflict with each other and with the brand''s unpublished rate, so no rate is recorded; both Rakuten Advertising and ShareASale are reported as routes in. No earnings-cap statement is published, so the cap is unknown.', 'publicly_reported', now());
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://www.nomnomnow.com/', 'official_site', 'general', 'Nom Nom''s official site describes gently cooked, vet-developed fresh dog food personalized to each dog, and its support pages confirm the meals are also sold through PetSmart, Amazon and Chewy; the brand''s own veterinary page states it is backed by Mars and Royal Canin regulatory and quality standards.', 'verified', now());
