  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://affiliatemarketinggirl.io/blog/10-mattress-affiliate-programs-you-can-promote-today', 'listing', 'affiliate', 'Mattress-program roundup (figures checked April 2025) reports a conflicting Helix structure: a flat $100-$125 per mattress via Impact with a 30-day cookie. Other listings report ~5% (Brandid) or up to 6% with a 90-day cookie (Ecommerce Paradise). Because published sources conflict (12% vs flat bounty vs 5-6%), commission_rate is null with the conflict recorded here.', 'publicly_reported', now());
