  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://linkclicky.com/affiliate-program/blueair/', 'listing', 'affiliate', 'LinkClicky program listing (which reads the network''s published terms): Blueair''s affiliate program runs on Impact and pays tiered commission of 2% per sale / 3% per sale. The starting tier (2%) is recorded as the rate. No earnings-cap statement is published, so the cap is unknown. (Lasso''s higher ''up to 11.25%'' figure is its Amazon Associates estimate, not the brand''s network program.)', 'publicly_reported', now());
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://builtin.com/job/affiliate-ugc-manager/11309230', 'listing', 'creator_program', 'Blueair''s own job posting for an Affiliate & UGC Manager (Built In) states the role will ''Own Blueair''s affiliate and user-generated content programs end to end, including partner and creator recruitment, contracting, budgets, campaigns, content approvals, product seeding, licensing, compliance, and performance reporting'' and will manage platforms such as ShopMy, LTK and GRIN — direct evidence the brand actively runs creator and UGC partnerships. The posting also confirms Blueair is part of Unilever.', 'publicly_reported', now());
