  insert into public.opportunities (brand_id, title, application_url, source_url, status, opportunity_type) values (bid, 'Saatva Partner Program — commission on luxury mattress sales (3% starting per its network profile; affsaatva@gmail.com)', 'https://ui.awin.com/merchant-profile/88129', 'https://ui.awin.com/merchant-profile/88129', 'unverified', 'ugc');
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://ui.awin.com/merchant-profile/88129', 'listing', 'affiliate', 'Saatva''s official Awin merchant profile fetched in full: ''Use affiliate tracking links on your social media or website to earn commission on sales''; the program is managed through the ShareASale dashboard with creative assets and text links; ''Earn commission starting at 3% on all Saatva sales generated through your website''; 90-day cookie duration; a dedicated program management team; and the affiliate team contact affsaatva@gmail.com published for program questions. The profile also states 800,000+ happy sleepers, 98% customer satisfaction and 155 delivery centers in the US & Canada.', 'publicly_reported', now());
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://affiliatemarketinggirl.io/blog/10-mattress-affiliate-programs-you-can-promote-today', 'listing', 'affiliate', 'A mattress-program roundup (figures checked April 2025) reports a different Saatva structure — flat $50-$700 per sale tiered by product, via Impact, with a 45-day cookie. Because published sources conflict (3% of sale via the ShareASale-run profile vs flat bounties via Impact), commission_rate is null with both structures recorded here. No earnings-cap statement is published, so the cap is unknown.', 'publicly_reported', now());
  insert into public.brand_scores (brand_id, niche_fit, ugc_evidence, compensation, contact_access, opportunity_availability, credibility, explanation) values (bid, 24, 12, 10, 13, 8, 5, '{"compensation": "High order values ($1,000-$6,000) make even a starting 3% meaningful, and flat bounties up to $700 are reported elsewhere \u2014 but the structures conflict, so the recorded rate stays null", "contact_access": "Published affiliate team email (affsaatva@gmail.com) plus a dedicated program management team, per the official profile", "credibility": "800,000+ sleepers and 98% customer satisfaction stated on the program''s own network profile", "niche_fit": "Mattresses and sleep upgrades are a staple home UGC category, and Saatva''s white-glove delivery story films well", "opportunity_availability": "Free network sign-up with no fees, per the official profile", "ugc_evidence": "Official profile explicitly invites promotion via affiliate links on social media as well as websites"}'::jsonb);
